#!/usr/bin/env python3
"""Generate checked-in SASLprep/NFKC data from Python's Unicode tables.

Development tool only. Preserve LICENSE-UNICODE; runtime uses no Python or crates.
SASLprep properties use Unicode 3.2; normalization uses the generator's pinned
Unicode version (including Corrigendum #4), matching Lazaret's PostgreSQL tests.
"""
from pathlib import Path
import stringprep as s
import unicodedata as u

assert u.unidata_version == '15.0.0', 'Use Python with Unicode 15.0.0 for reproducible tables'
prohibited = [s.in_table_c12, s.in_table_c21, s.in_table_c22, s.in_table_c3,
              s.in_table_c4, s.in_table_c5, s.in_table_c6, s.in_table_c7,
              s.in_table_c8, s.in_table_c9, s.in_table_a1]
properties, decompositions, combining, compositions = [], [], [], []
last, start = None, 0
for n in range(0x110000):
    c = chr(n)
    flags = (int(s.in_table_b1(c)) | (int(s.in_table_c12(c)) << 1)
             | (int(any(f(c) for f in prohibited)) << 2)
             | (int(s.in_table_d1(c)) << 3) | (int(s.in_table_d2(c)) << 4))
    if flags != last:
        if last: properties.append((start, n - 1, last))
        start, last = n, flags
    cc = u.combining(c)
    if cc: combining.append((n, cc))
    d = u.decomposition(c)
    if d:
        decompositions.append((n, [ord(x) for x in u.normalize('NFKD', c)]))
        if not d.startswith('<'):
            pieces = [int(x, 16) for x in d.split()]
            if len(pieces) == 2 and u.normalize('NFC', ''.join(map(chr, pieces))) == c:
                compositions.append(((pieces[0] << 32) | pieces[1], n))
if last: properties.append((start, 0x10ffff, last))
out = ['// Generated by tools/generate_unicode.py: Unicode 3.2 properties; NFKC 15.0.0.',
       '// Unicode data terms: ../LICENSE-UNICODE. Do not edit by hand.',
       'pub(super) const PROPERTIES: &[(u32,u32,u8)] = &[']
out += [f'({a},{b},{v}),' for a,b,v in properties]
out += ['];', 'pub(super) const COMBINING: &[(u32,u8)] = &[']
out += [f'({a},{b}),' for a,b in combining]
out += ['];', 'pub(super) const DECOMPOSITIONS: &[(u32,&[u32])] = &[']
out += [f'({n},&[{",".join(map(str,d))}]),' for n,d in decompositions]
out += ['];', 'pub(super) const COMPOSITIONS: &[(u64,u32)] = &[']
out += [f'({a},{b}),' for a,b in sorted(compositions)]
out += ['];', '']
Path(__file__).resolve().parents[1].joinpath('src/unicode_data.rs').write_text('\n'.join(out))
print({'properties':len(properties), 'decompositions':len(decompositions),
       'combining':len(combining), 'compositions':len(compositions)})
